27	/**
28	 * Simple JavaBean domain object representing an owner.
29	 *
30	 * @author Ken Krebs
31	 * @author Juergen Hoeller
32	 * @author Sam Brannen
33	 * @author Michael Isvy
34	 */
35	@Entity
36	@Table(name = "owners")
37	public class Owner extends Person {
38	    @Column(name = "address")
39	    @NotEmpty
40	    private String address;
41	
42	    @Column(name = "city")
43	    @NotEmpty
44	    private String city;
45	
46	    @Column(name = "telephone")
47	    @NotEmpty
48	    @Pattern(regexp = "^\\+[0-9]{8,15}$",
49	            message = "Phone number must be E.164: a '+' followed by 8 to 15 digits")
50	    private String telephone;
51	
52	    @Column(name = "email")
53	    private String email;
54	
55	    @Column(name = "registration_date")
56	    private LocalDate registrationDate;
57	
58	    @Column(name = "customer_code")
59	    private String customerCode;
60	
61	    @Column(name = "household_id")
62	    private String householdId;
63	
64	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
65	    private Set<Pet> pets;
66	
67	    public String getAddress() {
68	        return this.address;
69	    }
70	
71	    public void setAddress(String address) {
72	        this.address = address;
73	    }
74	
75	    public String getCity() {
76	        return this.city;
77	    }
78	
79	    public void setCity(String city) {
80	        this.city = city;
81	    }
82	
83	    public String getTelephone() {
84	        return this.telephone;
85	    }
86	
87	    public void setTelephone(String telephone) {
88	        this.telephone = telephone;
89	    }
90	
91	    public String getEmail() {
92	        return this.email;
93	    }
94	
95	    public void setEmail(String email) {
96	        this.email = email;
97	    }
98	
99	    public LocalDate getRegistrationDate() {
100	        return this.registrationDate;
101	    }
102	
103	    public void setRegistrationDate(LocalDate registrationDate) {
104	        this.registrationDate = registrationDate;
105	    }
106	
107	    public String getCustomerCode() {
108	        return this.customerCode;
109	    }
110	
111	    public void setCustomerCode(String customerCode) {
112	        this.customerCode = customerCode;
113	    }
114	
115	    public String getHouseholdId() {
116	        return this.householdId;
117	    }
118	
119	    public void setHouseholdId(String householdId) {
120	        this.householdId = householdId;
121	    }
122	
123	    protected Set<Pet> getPetsInternal() {
124	        if (this.pets == null) {
125	            this.pets = new HashSet<>();
126	        }
127	        return this.pets;
128	    }
129	
130	    protected void setPetsInternal(Set<Pet> pets) {
131	        this.pets = pets;
132	    }
133	
134	    public List<Pet> getPets() {
135	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
136	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
137	        return Collections.unmodifiableList(sortedPets);
138	    }
139	
140	    public void setPets(List<Pet> pets) {
141	        this.pets = new HashSet<>(pets);
142	    }
143	
144	    public void addPet(Pet pet) {
145	        getPetsInternal().add(pet);
146	        pet.setOwner(this);
147	    }
148	
149	    /**
150	     * Return the Pet with the given name, or null if none found for this Owner.
151	     *
152	     * @param name to test
153	     * @return true if pet name is already in use
154	     */
155	    public Pet getPet(String name) {
156	        return getPet(name, false);
157	    }
158	
159	    /**
160	     * Return the Pet with the given name, or null if none found for this Owner.
161	     *
162	     * @param name to test
163	     * @return true if pet name is already in use
164	     */
165	    public Pet getPet(String name, boolean ignoreNew) {
166	        name = name.toLowerCase();
167	        for (Pet pet : getPetsInternal()) {
168	            if (!ignoreNew || !pet.isNew()) {
169	                String compName = pet.getName();
170	                compName = compName.toLowerCase();
171	                if (compName.equals(name)) {
172	                    return pet;
173	                }
174	            }
175	        }
176	        return null;
177	    }
178	
179	    public Pet getPet(Integer petId) {
180	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
181	    }
182	
183	    @Override
184	    public String toString() {
185	        return new ToStringCreator(this)
186	
187	            .append("id", this.getId())
188	            .append("new", this.isNew())
189	            .append("lastName", this.getLastName())
190	            .append("firstName", this.getFirstName())
191	            .append("address", this.address)
192	            .append("city", this.city)
193	            .append("telephone", this.telephone)
194	            .toString();
195	    }
196	}
