9	/**
10	 * Rejects a create-owner request that would put two owners with the same last name at the same
11	 * address. Last name and address are compared case-insensitively with collapsed whitespace (leading
12	 * and trailing whitespace trimmed, internal runs of whitespace treated as a single space), so
13	 * "Smith" / "12  Main  St " collides with "smith" / "12 Main St". A collision is reported as a 409
14	 * (see {@link DuplicateHouseholdException}).
15	 *
16	 * <p>Runs after {@link CheckUniqueTelephone} (which republishes the validated request as a variable)
17	 * and before {@link BuildOwner}. A request that opts in with {@code sharesHousehold=true} is allowed
18	 * through, so intentionally shared households can be recorded.
19	 */
20	public class CheckUniqueHousehold {
21	
22	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
23	            throws DuplicateHouseholdException {
24	        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
25	            return;
26	        }
27	        String lastName = normalize(request.getLastName());
28	        String address = normalize(request.getAddress());
29	        for (Owner existing : ownerRepository.findAll()) {
30	            if (lastName.equals(normalize(existing.getLastName()))
31	                    && address.equals(normalize(existing.getAddress()))) {
32	                throw new DuplicateHouseholdException(request.getLastName(), request.getAddress());
33	            }
34	        }
35	    }
36	
37	    private static String normalize(String value) {
38	        if (value == null) {
39	            return "";
40	        }
41	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
42	    }
43	}
