14	/**
15	 * Assigns a shared {@code householdId} to owners that intentionally share a household.
16	 *
17	 * <p>Runs after {@link BuildOwner} (which produces the new {@link Owner}) and only acts when the
18	 * request opted in with {@code sharesHousehold=true}. It finds every existing owner with the same
19	 * last name and address (compared case-insensitively with collapsed whitespace, exactly as
20	 * {@link CheckUniqueHousehold} decides a collision). When at least one such owner exists — the
21	 * household this owner is joining — a stable identifier is chosen and stamped onto the new owner
22	 * and back-filled onto the existing members, so every owner in the household reports the same
23	 * {@code householdId}.
24	 *
25	 * <p>The identifier is derived deterministically from the normalized last name and address, so it
26	 * is the same value each joining owner computes regardless of ordering; an identifier already
27	 * present on an existing member is reused as-is.
28	 */
29	public class AssignHousehold {
30	
31	    public void service(@Val OwnerFieldsDto request, @Val Owner owner, OwnerRepository ownerRepository) {
32	        if (!Boolean.TRUE.equals(request.getSharesHousehold())) {
33	            return;
34	        }
35	        String lastName = normalize(owner.getLastName());
36	        String address = normalize(owner.getAddress());
37	        List<Owner> household = new ArrayList<>();
38	        for (Owner existing : ownerRepository.findAll()) {
39	            if (lastName.equals(normalize(existing.getLastName()))
40	                    && address.equals(normalize(existing.getAddress()))) {
41	                household.add(existing);
42	            }
43	        }
44	        if (household.isEmpty()) {
45	            // sharesHousehold was set but no existing member shares this address; nothing to join.
46	            return;
47	        }
48	        String householdId = existingHouseholdId(household);
49	        if (householdId == null) {
50	            householdId = deriveHouseholdId(lastName, address);
51	        }
52	        owner.setHouseholdId(householdId);
53	        for (Owner member : household) {
54	            if (!householdId.equals(member.getHouseholdId())) {
55	                member.setHouseholdId(householdId);
56	                ownerRepository.save(member);
57	            }
58	        }
59	    }
60	
61	    private static String existingHouseholdId(List<Owner> household) {
62	        for (Owner member : household) {
63	            String id = member.getHouseholdId();
64	            if (id != null && !id.isBlank()) {
65	                return id;
66	            }
67	        }
68	        return null;
69	    }
70	
71	    private static String deriveHouseholdId(String lastName, String address) {
72	        return "H-" + shaHex(lastName + "|" + address, 12);
73	    }
74	
75	    private static String shaHex(String value, int length) {
76	        try {
77	            byte[] digest = MessageDigest.getInstance("SHA-256")
78	                    .digest(value.getBytes(StandardCharsets.UTF_8));
79	            StringBuilder sb = new StringBuilder(digest.length * 2);
80	            for (byte b : digest) {
81	                sb.append(String.format("%02x", b));
82	            }
83	            return sb.substring(0, length).toUpperCase();
84	        }
85	        catch (NoSuchAlgorithmException ex) {
86	            throw new IllegalStateException("SHA-256 is required but unavailable", ex);
87	        }
88	    }
89	
90	    private static String normalize(String value) {
91	        if (value == null) {
92	            return "";
93	        }
94	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
95	    }
96	}
