19	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
20	            throws DuplicateTelephoneException {
21	        String telephone = normalize(request.getTelephone());
22	        for (Owner existing : ownerRepository.findAll()) {
23	            if (telephone.equals(normalize(existing.getTelephone()))) {
24	                throw new DuplicateTelephoneException(request.getTelephone());
25	            }
26	        }
27	    }
28	
29	    private static String normalize(String telephone) {
30	        try {
31	            return OwnerTelephone.toE164(telephone);
32	        }
33	        catch (InvalidTelephoneException ex) {
34	            // An existing (or already-normalized) value that cannot form E.164 simply cannot
35	            // collide with a valid E.164 request; represent it by its raw form.
36	            return telephone == null ? "" : telephone;
37	        }
38	    }
39	}
